function selectField(label,name,items,value){return `<label class="field">${label}<select name="${name}">${items.map(([v,l])=>`<option value="${v}" ${String(value)===String(v)?'selected':''}>${l}</option>`).join('')}</select></label>`;}
function badge(text){const kind={'达标':'red','待核验':'amber','临界':'','待复核':'blue','已确认':'red','误报':'','已录入 SaaS':'green','运行中':'blue','已完成':'green','失败':'red','排队中':'amber','已取消':'','启用':'green','停用':'','已发送':'green','未配置':'amber','有效':'green','失效':''}[text]||'';return `<span class="badge ${kind} dot">${esc(text)}</span>`;}
