function toast(text){$('#toasts').replaceChildren();const el=document.createElement('div');el.className='toast';el.textContent=text;$('#toasts').append(el);setTimeout(()=>el.remove(),3500);}
let restoreFocus=null;
function modal(title,body,foot='',wide=false,sub=''){
 const d=$('#modal');if(d.open)d.close();restoreFocus=document.activeElement;
 d.className=wide?'wide':'';d.innerHTML=`<div class="modal-head"><div><span class="eyebrow">${wide?'工作详情':'本地演示'}</span><h2 id="modal-title">${title}</h2>${sub?`<p>${sub}</p>`:''}</div><button class="icon" data-act="close" aria-label="关闭对话框">×</button></div><div class="modal-body">${body}</div>${foot?`<div class="modal-foot">${foot}</div>`:''}`;d.showModal();
}
function close(){const d=$('#modal');if(d.open&&$('#task-form'))saveTaskDraft();d.close();d.innerHTML='';if(restoreFocus?.isConnected)restoreFocus.focus();}
$('#modal').addEventListener('cancel',e=>{e.preventDefault();close();});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close();}});
