 $('#nav').innerHTML=`<span class="nav-label">日常工作</span>${['leads','tasks'].map(nav).join('')}${state.role!=='user'?`<span class="nav-label">业务管理</span>${nav('ips')}<span class="nav-label">系统管理</span>${['accounts','settings','update','logs'].map(nav).join('')}`:''}`;
 $('#role-name').textContent=roles[state.role];$('#role').value=state.role;
 $('#crumb').textContent=(['leads','tasks'].includes(state.view)?'工作区':state.view==='ips'?'业务管理':'系统与账户')+' / '+(labels[state.view]||'线索复核');
 document.title=(labels[state.view]||'线索复核')+' · 工作台设计预览';
